function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function rows($s,$p=[]){try{return gdb_all($s,$p)?:[];}catch(Throwable $e){return [];}}
function one($s,$p=[]){try{return gdb_one($s,$p)?:[];}catch(Throwable $e){return [];}}
function norm_exec($d){$k=strtolower(trim((string)$d));$k=preg_replace('/[^a-z]/','',$k);$aliases=['oliath'=>'goliath','essica'=>'jessica','cout'=>'scout','corsese'=>'scorsese','ozart'=>'mozart','hakespeare'=>'shakespeare','instein'=>'einstein','olumbo'=>'columbo','rospector'=>'prospector','ockefeller'=>'rockefeller','andora'=>'pandora','herlock'=>'sherlock'];return $aliases[$k]??$k;}
function iconx($d){$d=norm_exec($d);return ['goliath'=>'🏛️','jessica'=>'✉️','scout'=>'🕵️','scorsese'=>'🎬','mozart'=>'🎼','shakespeare'=>'✒️','einstein'=>'📊','sherlock'=>'🔎','columbo'=>'🕵️‍♂️','prospector'=>'⛏️','rockefeller'=>'💰','pandora'=>'🌍'][$d]??'⚡';}
function agent_url($d){
 $k=norm_exec($d);
 $map=[
  'goliath'=>'/dashboard/goliath-os.php',
  'scout'=>'/dashboard/scout-ready-contacts.php',
  'jessica'=>'/dashboard/jessica-relationship-center.php',
  'shakespeare'=>'/dashboard/shakespeare-authority-center.php',
  'einstein'=>'/dashboard/einstein-intelligence-center.php',
  'scorsese'=>'/dashboard/scorsese-studio-pro.php',
  'sherlock'=>'/dashboard/sherlock-strategy-lab.php',
  'pandora'=>'/dashboard/pandora-design-studio.php',
  'mozart'=>'/dashboard/mozart-audio-studio.php'
 ];
 return $map[$k]??('/dashboard/executive-office.php?exec='.rawurlencode($k));
}

$key=defined('AFTER_HOURS_CRON_KEY')?AFTER_HOURS_CRON_KEY:'timetomakethedonuts';

$brain=function_exists('gcb_company_snapshot')?gcb_company_snapshot():['by_executive'=>[],'counts'=>[],'opportunity_radar'=>[]];
if(isset($brain['by_executive']) && is_array($brain['by_executive'])){
  $fixed=[];
  foreach($brain['by_executive'] as $raw=>$stats){
    $k=norm_exec($raw);
    if(!isset($fixed[$k])) $fixed[$k]=$stats;
    else{
      foreach(['total','verified','needs'] as $f) $fixed[$k][$f]=(int)($fixed[$k][$f]??0)+(int)($stats[$f]??0);
      $fixed[$k]['score']=max((int)($fixed[$k]['score']??0),(int)($stats['score']??0));
      if(!empty($stats['latest'])) $fixed[$k]['latest']=$stats['latest'];
    }
  }
  $brain['by_executive']=$fixed;
}

