$content=rows("SELECT id,title,content_type,town,scenario,approval_status,status,published_path,created_at FROM shakespeare_content_packages ORDER BY CASE WHEN approval_status='needs_review' THEN 0 ELSE 1 END, created_at DESC LIMIT 12");
