$mc_render_queue=rows("SELECT id,title,status,progress,updated_at,error_message FROM scorsese_comfy_jobs WHERE status IN ('queued','retry','working','rendering','failed','error') ORDER BY updated_at DESC,id DESC LIMIT 8");
$mc_datasets=rows("SELECT * FROM internal_contact_sources ORDER BY id DESC LIMIT 8");
$mc_scout_counts=one("SELECT COUNT(*) total, SUM(CASE WHEN COALESCE(best_phone,'')<>'' OR COALESCE(phone_1,'')<>'' OR COALESCE(phone,'')<>'' THEN 1 ELSE 0 END) phones, SUM(CASE WHEN COALESCE(best_email,'')<>'' OR COALESCE(email_1,'')<>'' OR COALESCE(email,'')<>'' THEN 1 ELSE 0 END) emails FROM internal_crm_contacts");

$deliverables=[];
