<script>
let goliathFormDirty=false;document.addEventListener('input',e=>{if(e.target.closest('form'))goliathFormDirty=true;});document.addEventListener('change',e=>{if(e.target.closest('form'))goliathFormDirty=true;});
setInterval(()=>{const active=document.activeElement;const isTyping=active&&['INPUT','TEXTAREA','SELECT'].includes(active.tagName);const hasFileSelected=document.querySelector('input[type="file"]')?.files?.length>0;if(goliathFormDirty||isTyping||hasFileSelected)return;},60000);
const payload = <?=json_encode($payload?:['metrics'=>$metrics,'actions'=>$actions],JSON_UNESCAPED_SLASHES)?>;
const briefText = <?=json_encode($council['meeting_summary']??'Good morning, Mark. Run the Executive Council to generate today’s cinematic brief.')?>;
function addTab(label, fn){const tabs=document.getElementById('tabs');[...tabs.children].forEach(t=>t.classList.remove('active'));let b=document.createElement('button');b.className='tab active';b.textContent=label;b.onclick=fn;tabs.appendChild(b);}
function setScreen(html){document.getElementById('screenBody').innerHTML=html;}
function showBrief(){[...document.getElementById('tabs').children].forEach(t=>t.classList.remove('active'));document.getElementById('tabs').children[0].classList.add('active');let m=payload.metrics||{};let actions=payload.actions||[];setScreen(`<h1>Good morning, Mark.</h1><div class="lede">${briefText.replace(/\n/g,'<br>')}</div><div class="metricRow"><div class="metric"><b>${m.scout_ready||0}</b><span>Scout Ready</span></div><div class="metric"><b>${m.jessica_drafts||0}</b><span>Jessica Drafts</span></div><div class="metric"><b>${m.shakespeare_review||0}</b><span>Content Review</span></div><div class="metric"><b>${m.social_queue||0}</b><span>Social Queue</span></div><div class="metric"><b>${m.browser_queue||0}</b><span>Browser</span></div></div><div class="priority">${actions.map(a=>`<button onclick="window.location.href='${a.target||'#'}'"><b>${a.label}</b><div class="muted">${a.detail||''}</div></button>`).join('')}</div>`);}
function openDeliverable(d){addTab(d.type+': '+d.exec,()=>openDeliverable(d));setScreen(`<h1>${d.title}</h1><div class="lede">${d.detail}</div><div class="metricRow"><div class="metric"><b>${d.exec}</b><span>Executive</span></div><div class="metric"><b>${d.type}</b><span>Type</span></div></div><p><a class="btn gold" href="${d.url}">Open Full Workspace</a></p>`);}
function playMissionVideo(url){document.getElementById("missionVideoScreen").innerHTML='<video controls autoplay src="'+String(url).replace(/"/g,'&quot;')+'"></video>';}
showBrief();
</script></body></html>